from pathlib import Path
p=Path(__file__).with_name('viewer-template.html')
s=p.read_text(encoding='utf-8')
s=s.replace('<label><input type="checkbox" id="labels" checked>Labels</label>', ''.join('<label><input type="checkbox" data-layer="'+k+'" checked>'+v+'</label>' for k,v in [('toilets','Toilets / handwash'),('utilities','Water / help / lighting'),('traffic','Vehicle routes · proposed'),('pedestrian','Pedestrian routes · proposed'),('emergency','Emergency route · proposed'),('bridges','Overbridge · indicative'),('context','Nearby context')])+'<label><input type="checkbox" id="labels" checked>Labels</label>')
s=s.replace('d=b*Math.cos(pitch)-y*Math.sin(pitch)','d=b*Math.cos(pitch)+y*Math.sin(pitch)')
s=s.replace("const occupied=[];for(const l of DATA.labels)","const occupied=[];for(const l of DATA.labels)")
s=s.replace("if(document.getElementById('labels').checked)","for(const route of DATA.routes||[]){if(hidden.has(route.layer))continue;const pp=route.points.map(project);ctx.strokeStyle=route.color;ctx.lineWidth=2.5;ctx.setLineDash(route.layer==='emergency'?[7,5]:[]);ctx.beginPath();pp.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.stroke();ctx.setLineDash([]);for(let i=1;i<pp.length;i++){const a=pp[i-1],b=pp[i],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy);if(len<18)continue;let x=(a[0]+b[0])/2,y=(a[1]+b[1])/2,ux=dx/len,uy=dy/len;ctx.fillStyle=route.color;ctx.beginPath();ctx.moveTo(x+ux*7,y+uy*7);ctx.lineTo(x-ux*5-uy*4,y-uy*5+ux*4);ctx.lineTo(x-ux*5+uy*4,y-uy*5-ux*4);ctx.closePath();ctx.fill()}} if(document.getElementById('labels').checked)")
s=s.replace('sizes, stage, parking and routes are illustrative.', 'sizes, toilets, overbridge, parking and routes are illustrative; traffic routes are proposals, not an official diversion plan.')
s=s.replace('<div><b>D</b> &nbsp; Behind C · railway side</div>', '<div><b>D</b> &nbsp; Behind C · railway side</div><hr><div><span class="swatch" style="background:#d39a38"></span> Vehicle arrival · proposed</div><div><span class="swatch" style="background:#9b70a7"></span> Vehicle departure · proposed</div><div><span class="swatch" style="background:#378f99"></span> Pedestrian · proposed</div><div><span class="swatch" style="background:#c26352"></span> Emergency · proposed</div>')
p.write_text(s,encoding='utf-8')
